656  stream_peek_packet_hdr(pgp_source_t *src, pgp_packet_hdr_t *hdr)
   657  {
   658      size_t hlen = 0;
   659      memset(hdr, 0, sizeof(*hdr));
   660      if (!stream_pkt_hdr_len(src, &hlen)) {
   661          uint8_t hdr2[2] = {0};
   662          if (!src_peek_eq(src, hdr2, 2)) {
   663              RNP_LOG("pkt header read failed");
   664              return RNP_ERROR_READ;
   665          }
   666
   667          RNP_LOG("bad packet header: 0x%02x%02x", hdr2[0], hdr2[1]);
   668          return RNP_ERROR_BAD_FORMAT;
   669      }
   670
   671      if (!src_peek_eq(src, hdr->hdr, hlen)) {
   672          RNP_LOG("failed to read pkt header");
   673          return RNP_ERROR_READ;
   674      }
   675
   676      hdr->hdr_len = hlen;
   677      hdr->tag = (pgp_pkt_type_t) get_packet_type(hdr->hdr[0]);
   678
   679      if (stream_partial_pkt_len(src)) {
   680          hdr->partial = true;
   681      } else if (stream_intedeterminate_pkt_len(src)) {
   682          hdr->indeterminate = true;
   683      } else {
   684          (void) get_pkt_len(hdr->hdr, &hdr->pkt_len);
   685      }
   686
   687      return RNP_SUCCESS;
   688  }
