   690  rnp_result_t
   691  stream_read_packet_body(pgp_source_t *src, pgp_packet_body_t *body)
   692  {
   693      size_t len = 0;
   694      memset(body, 0, sizeof(*body));
   695
   696      /* Read the packet header and length */
   697      if (!stream_pkt_hdr_len(src, &len)) {
   698          return RNP_ERROR_BAD_FORMAT;
   699      }
   700
   701      if (!src_peek_eq(src, body->hdr, len)) {
   702          return RNP_ERROR_READ;
   703      }
   704
   705      body->hdr_len = len;
   706
   707      int ptag = get_packet_type(body->hdr[0]);
   708      if (ptag < 0) {
   709          return RNP_ERROR_BAD_FORMAT;
   710      }
   711      body->tag = (pgp_pkt_type_t) ptag;
   712
   713      if (!stream_read_pkt_len(src, &len)) {
   714          return RNP_ERROR_READ;
   715      }
   716
   717      /* early exit for the empty packet */
   718      if (!len) {
   719          return RNP_SUCCESS;
   720      }
   721
   722      if (len > PGP_MAX_PKT_SIZE) {
   723          RNP_LOG("too large packet");
   724          return RNP_ERROR_BAD_FORMAT;
   725      }
   726
   727      /* Read the packet contents */
   728      if (!(body->data = (uint8_t *) malloc(len))) {
   729          RNP_LOG("malloc of %d bytes failed", (int) len);
   730          return RNP_ERROR_OUT_OF_MEMORY;
   731      }
   732
   733      size_t read = 0;
   734      if (!src_read(src, body->data, len, &read) || (read != len)) {
   735          RNP_LOG("read %d instead of %d", (int) read, (int) len);
   736          free(body->data);
   737          body->data = NULL;
   738          return RNP_ERROR_READ;
   739      }
   740
   741      body->allocated = len;
   742      body->len = len;
   743      body->pos = 0;
   744      return RNP_SUCCESS;
   745  }
