   756  static rnp_result_t
   757  stream_read_packet_indeterminate(pgp_source_t *src, pgp_dest_t *dst)
   758  {
   759      uint8_t *buf = NULL;
   760      buf = (uint8_t *) malloc(PGP_INPUT_CACHE_SIZE);
   761      if (!buf) {
   762          return RNP_ERROR_OUT_OF_MEMORY;
   763      }
   764      while (!src_eof(src)) {
   765          size_t len = 0;
   766          if (!src_read(src, buf, PGP_INPUT_CACHE_SIZE, &len)) {
   767              free(buf);
   768              return RNP_ERROR_READ;
   769          }
   770          if (dst) {
   771              dst_write(dst, buf, len);
   772          }
   773      }
   774
   775      free(buf);
   776      return RNP_SUCCESS;
   777  }
